/**
 * The storylet pool (QBN). Every card: prerequisites over FactContext, a specificity score (how many
 * situational predicates hold — the Valve matcher prefers the most specific), urgency, cooldown, tension,
 * and a pure `build` that returns text + declarative choices. Age appears only as a soft bound.
 * Matrix cells are in units of u = 15 % of yearly income; the host converts to currency.
 */
import type { Storylet, FactContext, StoryletView, Choice, CastRole } from "./types.ts";
import { countTrue as n } from "./Matcher.ts";
import { prov } from "./Causality.ts";

const C = (label: string, effects: Choice["effects"], hint?: string, extra: Partial<Choice> = {}): Choice => ({ label, ...(hint !== undefined ? { hint } : {}), effects, ...extra });
type Matrix = NonNullable<StoryletView["matrix"]>;
const pd = (who: string, a = "Hợp tác", b = "Phản bội"): Matrix => ({ me: [a, b], them: [a, b], cells: [[[2, 2], [-2.7, 4]], [[4, -2.7], [-1.3, -1.3]]], unit: "u" });
const role = (ctx: FactContext, r: CastRole): string | undefined => ctx.cast[r];
const op = (ctx: FactContext, id: string | undefined): number => (id ? ctx.opinion[id] ?? 0 : 0);
const hasHook = (ctx: FactContext, id: string | undefined): boolean => !!id && (ctx.hooks[id]?.length ?? 0) > 0;
const nonFamily = (r: CastRole) => !["mother", "father", "sibling", "spouse", "child"].includes(r);

